// ICSE 10 Mathematics ch08 Matrices — practice bank with independent re-solve checks.
// Givens are integer matrices (mat); answers and every matrix inside a solution or model answer are
// typed as literals (M('a b; c d')), and each check recomputes them with mat.mjs (exact integer
// arithmetic) and compares the LaTeX strings, so a typed slip stops the build. Row-by-column working
// lines are generated from the givens (prodWork). MCQ option matrices are read back from the option
// text (optKey) so exactly one option equals the re-solved answer; distractors are recomputed from the
// slip they model (entrywise products, columns instead of rows, a dropped sign, a missed halving).
// All arithmetic stays within order 2 x 2 (ICSE 2027); mul() refuses anything larger.
import { Q, mk, r } from './lib.mjs';
import { mat, M, bm, key, optKey, parseBm, mul, add, sub, scal, sq, I2, O, eqM, T, hadamard, isRow, isCol, isSquare, isZero, isIdentity, canAdd, canMulO, prodOrder, prodWork, entryWork, entry, solveInt, sumAll, trace, rows, cols, order } from './mat.mjs';

const J = (lines) => lines.join('\n\n');
const d = (s) => `$${s}$`;
const keys = (opts) => opts.map(optKey);
const ok = (o) => o.join('x');

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`A matrix has $3$ rows and $2$ columns. What is its order?`, opts: [r`$3 \times 2$`, r`$2 \times 3$`, '$6$', '$5$'], key: 'a', sol: r`The order is written as (number of rows) by (number of columns), so it is $3 \times 2$. Option (b) swaps rows and columns, (c) is the number of elements and (d) adds the rows and columns.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { const A = mat('1 0; 4 7; -2 5'); C.which(['3x2', '2x3', '6', '5'], `${rows(A)}x${cols(A)}`); C.assert(A.flat().length === 6, '(c) is the element count'); });

const A02 = mat('4 0 -7');
Q('m02', mk.mcq({ stem: r`What kind of matrix is $${bm(A02)}$, and what is its order?`, opts: [r`A row matrix of order $1 \times 3$`, r`A column matrix of order $3 \times 1$`, r`A square matrix of order $3$`, r`A row matrix of order $3 \times 1$`], key: 'a', sol: r`It has one row and three columns, so it is a row matrix of order $1 \times 3$. The order always gives the rows first.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => C.which(['row1x3', 'col3x1', 'sq3', 'row3x1'], `${isRow(A02) ? 'row' : isCol(A02) ? 'col' : 'sq'}${rows(A02)}x${cols(A02)}`));

const o03 = [M('1 0; 0 1'), M('0 1; 1 0'), M('1 1; 1 1'), M('1 0; 0 0')];
Q('m03', mk.mcq({ stem: r`Pick the identity matrix of order $2$: the matrix that leaves every square matrix of order $2$ unchanged when it multiplies it.`, opts: o03.map(d), key: 'a', sol: r`The identity matrix has $1$ in each place of the leading diagonal (top left to bottom right) and $0$ everywhere else. Option (b) has its $1$s on the other diagonal, and (d) has a $0$ on the leading diagonal.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { C.which(o03.map((t) => (isIdentity(parseBm(t)) ? 1 : 0)), 1); const S = mat('3 -2; 5 7'); C.assert(eqM(mul(S, I2), S) && !eqM(mul(S, mat('0 1; 1 0')), S), 'identity leaves S unchanged, (b) does not'); });

Q('m04', mk.mcq({ stem: r`If $\begin{bmatrix} x + 3 & 5 \\ -1 & 2y \end{bmatrix} = ${M('7 5; -1 -6')}$, what is the value of $x + y$?`, opts: ['$1$', '$7$', '$-2$', '$4$'], key: 'a', sol: r`Equal matrices have equal corresponding elements: $x + 3 = 7$ gives $x = 4$, and $2y = -6$ gives $y = -3$. So $x + y = 4 + (-3) = 1$. Option (b) uses $y = 3$, and (c) forgets to halve $-6$.`, d: 2, c: 'application', t: [1], time: 75 }), (C) => { const x = 7 - 3, y = -6 / 2; C.which([1, 7, -2, 4], x + y); C.assert(x + 3 === 7 && 4 + 3 === 7 && 4 - 6 === -2, 'distractors (b) and (c)'); });

const p05 = [['3; -1', '0; 8'], ['3 -1', '0; 8'], ['2 5; 1 0', '4; 6'], ['7 2', '1 0; 0 1']];
Q('m05', mk.mcq({ stem: r`Matrix addition needs matching orders. In which pair below can the two matrices be added?`, opts: p05.map(([x, y]) => `$${M(x)}$ and $${M(y)}$`), key: 'a', sol: r`Only (a) has two matrices of the same order, $2 \times 1$ and $2 \times 1$. The other pairs have orders $1 \times 2$ and $2 \times 1$, $2 \times 2$ and $2 \times 1$, and $1 \times 2$ and $2 \times 2$.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => C.which(p05.map(([x, y]) => (canAdd(mat(x), mat(y)) ? 1 : 0)), 1));

Q('m06', mk.mcq({ stem: r`If $A$ is a $2 \times 2$ matrix and $B$ is a $2 \times 1$ matrix, the product $AB$ is`, opts: [r`a $2 \times 1$ matrix`, r`a $2 \times 2$ matrix`, r`a $1 \times 2$ matrix`, 'not defined'], key: 'a', sol: r`$AB$ is defined because $A$ has $2$ columns and $B$ has $2$ rows. The product takes the rows of $A$ and the columns of $B$, so its order is $2 \times 1$.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { const o = prodOrder([2, 2], [2, 1]); C.which(['2x1', '2x2', '1x2', 'none'], o ? ok(o) : 'none'); C.assert(rows(mul(mat('1 2; 3 4'), mat('5; 6'))) === 2, 'sample product is 2 x 1'); });

Q('m07', mk.mcq({ stem: r`$P$ is a column matrix of order $2 \times 1$ and $Q$ is a square matrix of order $2 \times 2$. Which of the products $PQ$ and $QP$ can be found?`, opts: [r`$QP$ only`, r`$PQ$ only`, r`Both $PQ$ and $QP$`, 'Neither of them'], key: 'a', sol: r`For $PQ$, $P$ has $1$ column but $Q$ has $2$ rows, so $PQ$ is not defined. For $QP$, $Q$ has $2$ columns and $P$ has $2$ rows, so $QP$ is defined, of order $2 \times 1$.`, d: 2, c: 'analysis', t: [2], time: 60 }), (C) => { const pq = canMulO([2, 1], [2, 2]), qp = canMulO([2, 2], [2, 1]); C.which(['QP', 'PQ', 'both', 'neither'], pq && qp ? 'both' : pq ? 'PQ' : qp ? 'QP' : 'neither'); });

const A08 = mat('5 -2; 3 0'), B08 = mat('1 4; -3 6');
const o08 = [M('6 2; 0 6'), M('4 -6; 6 -6'), M('-4 6; -6 6'), M('5 -8; -9 0')];
Q('m08', mk.mcq({ stem: r`Given $A = ${bm(A08)}$ and $B = ${bm(B08)}$, find $A + B$.`, opts: o08.map(d), key: 'a', sol: r`Add corresponding elements: $A + B = \begin{bmatrix} 5 + 1 & -2 + 4 \\ 3 + (-3) & 0 + 6 \end{bmatrix} = ${M('6 2; 0 6')}$. Option (b) is $A - B$, (c) is $B - A$ and (d) multiplies corresponding elements.`, d: 1, c: 'understanding', t: [3], time: 45 }), (C) => { C.which(keys(o08), key(add(A08, B08))); C.assert(optKey(o08[1]) === key(sub(A08, B08)) && optKey(o08[2]) === key(sub(B08, A08)) && optKey(o08[3]) === key(hadamard(A08, B08)), 'distractors'); C.sol([bm(add(A08, B08))]); });

const A09 = mat('4 -6; 2 8');
const o09 = [M('6 -9; 3 12'), M('2 -3; 1 4'), M('12 -18; 6 24'), M('6 -9; 2 8')];
Q('m09', mk.mcq({ stem: r`If $A = ${bm(A09)}$, which matrix is $\dfrac{3}{2}A$?`, opts: o09.map(d), key: 'a', sol: r`Multiply every element by $\dfrac{3}{2}$: for example $\dfrac{3}{2} \times 4 = 6$ and $\dfrac{3}{2} \times (-6) = -9$. Option (b) is $\dfrac{1}{2}A$, (c) is $3A$, and (d) multiplies only the first row.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { C.which(keys(o09), key(scal([3, 2], A09))); C.assert(optKey(o09[1]) === key(scal([1, 2], A09)) && optKey(o09[2]) === key(scal(3, A09)) && optKey(o09[3]) === key([scal([3, 2], A09)[0], A09[1]]), 'distractors'); });

const A10 = mat('3 -1; 5 2'), B10 = mat('7 9; -1 4');
const o10 = [M('2 5; -3 1'), M('4 10; -6 2'), M('5 4; 2 3'), M('-2 -5; 3 -1')];
Q('m10', mk.mcq({ stem: r`Find the matrix $X$ for which $2X + A = B$, where $A = ${bm(A10)}$ and $B = ${bm(B10)}$.`, opts: o10.map(d), key: 'a', sol: r`$2X = B - A = ${M('4 10; -6 2')}$, so $X = \dfrac{1}{2}(B - A) = ${M('2 5; -3 1')}$. Option (b) forgets to halve, (c) halves $A + B$, and (d) halves $A - B$.`, d: 2, c: 'application', t: [3], time: 90 }), (C) => { const X = scal([1, 2], sub(B10, A10)); C.which(keys(o10), key(X)); C.assert(eqM(add(scal(2, X), A10), B10), '2X + A = B'); C.assert(optKey(o10[1]) === key(sub(B10, A10)) && optKey(o10[2]) === key(scal([1, 2], add(A10, B10))) && optKey(o10[3]) === key(scal([1, 2], sub(A10, B10))), 'distractors'); C.sol([bm(sub(B10, A10)), bm(X)]); });

const A11 = mat('2 3; -1 5'), B11 = mat('5; -2');
const o11 = [M('4; -15'), M('12; 5'), M('4 -15'), M('16; 5')];
Q('m11', mk.mcq({ stem: r`Work out the product $${bm(A11)}${bm(B11)}$.`, opts: o11.map(d), key: 'a', sol: r`Row by column: $${bm(A11)}${bm(B11)} = ${prodWork(A11, B11)} = ${M('4; -15')}$. Option (b) multiplies the columns of the first matrix by the column, (c) has the wrong order (a $2 \times 2$ matrix times a $2 \times 1$ matrix gives a $2 \times 1$ matrix), and (d) ignores the minus sign of $-2$.`, d: 2, c: 'application', t: [4], time: 75 }), (C) => { C.which(keys(o11), key(mul(A11, B11))); C.assert(optKey(o11[1]) === key(mul(T(A11), B11)) && optKey(o11[2]) === key(T(mul(A11, B11))) && optKey(o11[3]) === key(mul(A11, mat('5; 2'))), 'distractors'); });

const A12 = mat('1 3; 0 -1');
const o12 = [M('1 0; 0 1'), M('1 9; 0 1'), M('2 6; 0 -2'), M('0 0; 0 0')];
Q('m12', mk.mcq({ stem: r`For $A = ${bm(A12)}$, the matrix $A^2$ equals`, opts: o12.map(d), key: 'a', sol: r`$A^2 = A \times A = ${prodWork(A12, A12)} = ${M('1 0; 0 1')}$, the identity matrix. Option (b) squares each element, and (c) is $2A$.`, d: 2, c: 'application', t: [4], time: 75 }), (C) => { C.which(keys(o12), key(sq(A12))); C.assert(optKey(o12[1]) === key(hadamard(A12, A12)) && optKey(o12[2]) === key(scal(2, A12)) && isIdentity(sq(A12)), 'distractors; A^2 = I'); });

const S13 = [mat('3 -2; 5 7'), mat('0 4; -1 6'), mat('-8 1; 2 2')];
Q('m13', mk.mcq({ stem: r`Let $A$ be any square matrix of order $2$ and $I$ the identity matrix of order $2$. Which statement is always true?`, opts: [r`$AI = IA = A$`, r`$AI = I$`, r`$A + I = A$`, r`$IA = O$`], key: 'a', sol: r`Multiplying by the identity matrix, on either side, leaves a matrix unchanged: $AI = IA = A$. The other statements fail for a matrix such as $${M('3 -2; 5 7')}$.`, d: 1, c: 'recall', t: [4], time: 30 }), (C) => { const all = (fn) => (S13.every(fn) ? 1 : 0); C.which([all((A) => eqM(mul(A, I2), A) && eqM(mul(I2, A), A)), all((A) => eqM(mul(A, I2), I2)), all((A) => eqM(add(A, I2), A)), all((A) => isZero(mul(I2, A)))], 1); });

const A14 = mat('2 -2; 1 -1'), B14 = mat('3 6; 3 6');
Q('m14', mk.mcq({ stem: r`For $A = ${bm(A14)}$ and $B = ${bm(B14)}$, which statement about the products $AB$ and $BA$ is true?`, opts: [r`$AB = O$ but $BA \ne O$`, r`$AB = BA = O$`, r`$BA = O$ but $AB \ne O$`, r`Neither $AB$ nor $BA$ is $O$`], key: 'a', sol: r`$AB = ${prodWork(A14, B14)} = ${M('0 0; 0 0')}$, but $BA = ${prodWork(B14, A14)} = ${M('12 -12; 12 -12')}$. So $AB = O$ even though neither matrix is $O$, and $BA \ne O$.`, d: 3, c: 'analysis', t: [4], time: 120 }), (C) => { const z1 = isZero(mul(A14, B14)), z2 = isZero(mul(B14, A14)); C.which(['a', 'b', 'c', 'd'], z1 && !z2 ? 'a' : z1 && z2 ? 'b' : !z1 && z2 ? 'c' : 'd'); C.sol([bm(mul(B14, A14))]); });

Q('m15', mk.mcq({ stem: r`Find $x$ if $\begin{bmatrix} 3 & x \\ -1 & 2 \end{bmatrix} ${M('2; 1')} = ${M('10; 0')}$.`, opts: ['$4$', '$5$', '$16$', '$-4$'], key: 'a', sol: r`The first row of the product is $3 \times 2 + x \times 1 = 6 + x$, so $6 + x = 10$ and $x = 4$. The second row checks: $-1 \times 2 + 2 \times 1 = 0$. Option (b) divides $10$ by $2$, and (c) adds $6$ instead of subtracting it.`, d: 2, c: 'application', t: [4], time: 75 }), (C) => { const x = 10 - 3 * 2; C.which([4, 5, 16, -4], x); C.assert(key(mul(mat(`3 ${x}; -1 2`), mat('2; 1'))) === key(mat('10; 0')), 'product checks'); });

const A16 = mat('0 3; -3 0');
const o16 = [M('-9 0; 0 -9'), M('9 0; 0 9'), M('0 9; 9 0'), M('0 0; 0 0')];
Q('m16', mk.mcq({ stem: r`What is $A^2$ when $A = ${bm(A16)}$?`, opts: o16.map(d), key: 'a', sol: r`$A^2 = ${prodWork(A16, A16)} = ${M('-9 0; 0 -9')}$, which is $-9I$. Option (b) loses the minus signs, and (c) squares each element.`, d: 3, c: 'application', t: [4], time: 75 }), (C) => { C.which(keys(o16), key(sq(A16))); C.assert(eqM(sq(A16), scal(-9, I2)) && optKey(o16[2]) === key(hadamard(A16, A16)), '-9I; (c)'); });

const A17 = mat('-3 8; 0 -5');
const o17 = [M('3 -8; 0 5'), M('-3 8; 0 -5'), M('3 8; 0 5'), M('0 0; 0 0')];
Q('m17', mk.mcq({ stem: r`Which matrix $X$ satisfies $A + X = O$, where $A = ${bm(A17)}$ and $O$ is the zero matrix of order $2$?`, opts: o17.map(d), key: 'a', sol: r`$X = -A$: change the sign of every element of $A$. Option (b) is $A$ itself, (c) drops every minus sign instead of changing signs, and (d) is $O$.`, d: 2, c: 'understanding', t: [3], time: 45 }), (C) => { const X = scal(-1, A17); C.which(keys(o17), key(X)); C.assert(isZero(add(A17, X)), 'A + X = O'); });

const ord18 = { A: [1, 2], B: [2, 2], C: [2, 1] };
const pairs18 = [['B', 'A'], ['A', 'B'], ['B', 'C'], ['A', 'C']];
Q('m18', mk.mcq({ stem: r`$A$ is of order $1 \times 2$, $B$ is of order $2 \times 2$ and $C$ is of order $2 \times 1$. Which product is NOT defined?`, opts: pairs18.map(([x, y]) => `$${x}${y}$`), key: 'a', sol: r`$BA$ is not defined: $B$ has $2$ columns but $A$ has only $1$ row. $AB$ is $1 \times 2$, $BC$ is $2 \times 1$ and $AC$ is $1 \times 1$.`, d: 2, c: 'analysis', t: [2], time: 60 }), (C) => C.which(pairs18.map(([x, y]) => (canMulO(ord18[x], ord18[y]) ? 1 : 0)), 0));

const A19 = mat('4 1; -1 2');
Q('m19', mk.mcq({ stem: r`If $A = ${bm(A19)}$ and $A^2 - 6A + kI = O$, find the number $k$.`, opts: ['$9$', '$-9$', '$6$', '$3$'], key: 'a', sol: r`$A^2 = ${prodWork(A19, A19)} = ${M('15 6; -6 3')}$ and $6A = ${M('24 6; -6 12')}$, so $A^2 - 6A = ${M('-9 0; 0 -9')} = -9I$. Then $-9I + kI = O$ gives $k = 9$. Option (b) forgets to move $-9I$ across.`, d: 3, c: 'application', t: [4], time: 120 }), (C) => { const D = sub(sq(A19), scal(6, A19)); C.assert(D[0][1] === 0 && D[1][0] === 0 && D[0][0] === D[1][1], 'A^2 - 6A is a multiple of I'); const k = -D[0][0]; C.which([9, -9, 6, 3], k); C.assert(isZero(add(D, scal(k, I2))), 'k checks'); C.sol([bm(sq(A19)), bm(scal(6, A19)), bm(D)]); });

const A20 = mat('1 -2'), B20 = mat('3 0; 4 5');
const o20 = [M('-5 -10'), M('11 10'), M('-5; -10'), M('3 0; -8 -10')];
Q('m20', mk.mcq({ stem: r`Work out the product of the row matrix $${bm(A20)}$ and the square matrix $${bm(B20)}$, taken in that order.`, opts: o20.map(d), key: 'a', sol: r`$${bm(A20)}${bm(B20)} = ${prodWork(A20, B20)} = ${M('-5 -10')}$, a $1 \times 2$ matrix. Option (b) ignores the minus sign of $-2$, (c) has the wrong order, and (d) multiplies each row of the square matrix by one element.`, d: 2, c: 'application', t: [4], time: 75 }), (C) => { C.which(keys(o20), key(mul(A20, B20))); C.assert(optKey(o20[1]) === key(mul(mat('1 2'), B20)) && optKey(o20[2]) === key(T(mul(A20, B20))) && optKey(o20[3]) === key([B20[0].map((v) => v * A20[0][0]), B20[1].map((v) => v * A20[0][1])]), 'distractors'); });

// =============================================================== Assertion-reason (keys c a d b a d)
const P01 = scal(2, I2);
Q('ar1', mk.ar({ a: r`For $P = ${bm(P01)}$ and any square matrix $Q$ of order $2$, $PQ = QP$.`, r: r`Multiplication of matrices is commutative.`, key: 'c', sol: r`A is true: $P = 2I$, so $PQ = 2Q = QP$ for every $Q$. R is false: in general $AB \ne BA$; for example $${M('0 1; 0 0')}${M('0 0; 1 0')} = ${M('1 0; 0 0')}$ but $${M('0 0; 1 0')}${M('0 1; 0 0')} = ${M('0 0; 0 1')}$.`, d: 3, c: 'analysis', t: [4] }), (C) => { C.assert([mat('3 -2; 5 7'), mat('0 4; -1 6'), mat('-8 1; 2 2')].every((Qm) => eqM(mul(P01, Qm), mul(Qm, P01)) && eqM(mul(P01, Qm), scal(2, Qm))), 'A true'); const X = mat('0 1; 0 0'), Y = mat('0 0; 1 0'); C.assert(!eqM(mul(X, Y), mul(Y, X)), 'R false'); C.sol([bm(mul(X, Y)), bm(mul(Y, X))]); C.key('c'); });
Q('ar2', mk.ar({ a: r`A matrix of order $2 \times 1$ cannot be added to a matrix of order $1 \times 2$.`, r: r`Two matrices can be added only when they have the same order.`, key: 'a', sol: r`R is the rule for addition, and the two orders in A are different, so A follows from R. Both are true and R explains A.`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(!canAdd(mat('1; 2'), mat('1 2')), 'A true'); C.key('a'); });
const A03 = mat('3 6; 1 2'), B03 = mat('-2 4; 1 -2');
Q('ar3', mk.ar({ a: r`If $A$ and $B$ are square matrices of order $2$ with $AB = O$, then $A = O$ or $B = O$.`, r: r`The product of two non-zero matrices can be the zero matrix.`, key: 'd', sol: r`R is true: $${bm(A03)}${bm(B03)} = ${M('0 0; 0 0')}$ although neither matrix is $O$. That same example shows A is false.`, d: 2, c: 'understanding', t: [4] }), (C) => { C.assert(isZero(mul(A03, B03)) && !isZero(A03) && !isZero(B03), 'R true, A false'); C.key('d'); });
Q('ar4', mk.ar({ a: r`The zero matrix $${M('0 0; 0 0')}$ is a square matrix.`, r: r`Every element of a zero matrix is $0$.`, key: 'b', sol: r`A is true because the matrix has as many rows as columns, $2$ each. R is also true, but having zero elements does not make a matrix square: $${M('0 0')}$ is a zero matrix of order $1 \times 2$.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(isSquare(O(2)) && isZero(O(2)) && isZero(mat('0 0')) && !isSquare(mat('0 0')), 'A, R true; R does not explain A'); C.key('b'); });
Q('ar5', mk.ar({ a: r`If $2X = ${M('4 -6; 10 2')}$, then $X = ${M('2 -3; 5 1')}$.`, r: r`To multiply a matrix by a number, multiply every element by that number.`, key: 'a', sol: r`Multiplying both sides by $\dfrac{1}{2}$ multiplies every element by $\dfrac{1}{2}$, which gives the matrix stated in A. Both are true and R explains A.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(key(scal([1, 2], mat('4 -6; 10 2'))) === key(mat('2 -3; 5 1')), 'A true'); C.key('a'); });
const A06 = mat('3 1; 0 1');
Q('ar6', mk.ar({ a: r`For $A = ${bm(A06)}$, $A^2 = ${M('9 1; 0 1')}$.`, r: r`$A^2$ means $A \times A$, found by multiplying the rows of $A$ by the columns of $A$.`, key: 'd', sol: r`R is true. Using R, $A^2 = ${prodWork(A06, A06)} = ${M('9 4; 0 1')}$. The matrix in A only squares each element, so A is false.`, d: 2, c: 'application', t: [4] }), (C) => { C.assert(key(sq(A06)) === key(mat('9 4; 0 1')) && key(hadamard(A06, A06)) === key(mat('9 1; 0 1')), 'A false'); C.sol([bm(sq(A06))]); C.key('d'); });

// =============================================================== True / false
Q('tf1', mk.tf({ stem: r`A matrix of order $2 \times 2$ has exactly $4$ elements.`, key: 't', sol: r`It has $2$ rows of $2$ elements each: $2 \times 2 = 4$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert(mat('1 2; 3 4').flat().length === 4, '4 elements'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`Every square matrix of order $2$ is an identity matrix.`, key: 'f', sol: r`An identity matrix needs $1$ on the leading diagonal and $0$ elsewhere. $${M('4 1; 2 3')}$ is square but is not an identity matrix.`, d: 1, c: 'understanding', t: [1] }), (C) => { const A = mat('4 1; 2 3'); C.assert(isSquare(A) && !isIdentity(A), 'counter-example'); C.key('f'); });
const X03 = mat('1 4; 0 3'), Y03 = mat('0 1; 1 0');
Q('tf3', mk.tf({ stem: r`For any two square matrices $A$ and $B$ of order $2$, the products $AB$ and $BA$ are always equal.`, key: 'f', sol: r`Take $A = ${bm(X03)}$ and $B = ${bm(Y03)}$: $AB = ${M('4 1; 3 0')}$ but $BA = ${M('0 3; 1 4')}$.`, d: 2, c: 'understanding', t: [4] }), (C) => { C.assert(!eqM(mul(X03, Y03), mul(Y03, X03)), 'AB differs from BA'); C.sol([bm(mul(X03, Y03)), bm(mul(Y03, X03))]); C.key('f'); });
Q('tf4', mk.tf({ stem: r`If $A$ and $B$ are both column matrices of order $2 \times 1$, then $A - B$ is also of order $2 \times 1$.`, key: 't', sol: r`Subtraction works element by element on matrices of the same order, and the result keeps that order.`, d: 1, c: 'understanding', t: [3] }), (C) => { const D = sub(mat('4; -1'), mat('6; 2')); C.assert(rows(D) === 2 && cols(D) === 1, '2 x 1'); C.key('t'); });
const A25 = mat('1 0; 0 0'), B25 = mat('0 1; 0 0');
Q('tf5', mk.tf({ stem: r`For all square matrices $A$ and $B$ of order $2$, $(A + B)^2 = A^2 + 2AB + B^2$.`, key: 'f', sol: r`$(A + B)^2 = A^2 + AB + BA + B^2$, which equals $A^2 + 2AB + B^2$ only when $AB = BA$. For $A = ${bm(A25)}$ and $B = ${bm(B25)}$, $(A + B)^2 = ${M('1 1; 0 0')}$ but $A^2 + 2AB + B^2 = ${M('1 2; 0 0')}$.`, d: 3, c: 'analysis', t: [4] }), (C) => { const L = sq(add(A25, B25)), R = add(add(sq(A25), scal(2, mul(A25, B25))), sq(B25)); C.assert(!eqM(L, R), 'counter-example'); C.sol([bm(L), bm(R)]); C.key('f'); });
Q('tf6', mk.tf({ stem: r`The product of a $2 \times 1$ column matrix and a $2 \times 2$ matrix, taken in that order, is defined.`, key: 'f', sol: r`The column matrix has $1$ column but the square matrix has $2$ rows; these must be equal, so the product is not defined. (The other order, square matrix first, is defined.)`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(!canMulO([2, 1], [2, 2]) && canMulO([2, 2], [2, 1]), 'not defined; reverse defined'); C.key('f'); });

// =============================================================== Fill in the blank
const A31 = mat('5 -3; 8 0');
Q('fb1', mk.fill({ stem: r`In the matrix $${bm(A31)}$, the element in the second row and first column is ___.`, acc: [['8']], sol: r`The second row is $8, 0$; its first element is $8$.`, d: 1, c: 'recall', t: [1] }), (C) => C.blank(entry(A31, 2, 1)));
Q('fb2', mk.fill({ stem: r`If $\begin{bmatrix} 2a & 3 \\ 1 & b + 4 \end{bmatrix} = ${M('10 3; 1 1')}$, then $b =$ ___.`, acc: [['-3', '−3']], sol: r`Corresponding elements are equal: $b + 4 = 1$, so $b = -3$ (and $2a = 10$ gives $a = 5$).`, d: 1, c: 'understanding', t: [1] }), (C) => { C.blank(1 - 4); C.assert(10 / 2 === 5, 'a = 5'); });
Q('fb3', mk.fill({ stem: r`A matrix $P$ of order $1 \times 2$ is multiplied on the right by a matrix $Q$ of order $2 \times 2$. The order of $PQ$ is ___.`, acc: [['1 × 2', '1 x 2', '1x2', '1×2', '1 by 2']], sol: r`$P$ has $1$ row and $Q$ has $2$ columns, so $PQ$ is 1 × 2.`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(ok(prodOrder([1, 2], [2, 2])) === '1x2', '1 x 2'); C.blank('1 × 2'); });
const A34 = mat('3 -1; 5 2');
Q('fb4', mk.fill({ stem: r`The sum of all the elements of $2A$, where $A = ${bm(A34)}$, is ___.`, acc: [['18']], sol: r`$2A = ${M('6 -2; 10 4')}$, and $6 + (-2) + 10 + 4 = 18$.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.blank(sumAll(scal(2, A34))); C.sol([bm(scal(2, A34))]); });
Q('fb5', mk.fill({ stem: r`For every square matrix $A$ of order $2$, the product of $A$ and the identity matrix $I$ of order $2$, in either order, equals ___.`, acc: [['A', '$A$']], sol: r`The identity matrix leaves a matrix unchanged: AI = IA = A.`, d: 1, c: 'recall', t: [4] }), (C) => { const A = mat('-2 5; 7 1'); C.assert(eqM(mul(A, I2), A) && eqM(mul(I2, A), A), 'AI = IA = A'); C.blank('A'); });
const A36 = mat('2 5; 1 4'), B36 = mat('4 -1; 0 2');
Q('fb6', mk.fill({ stem: r`The element in the first row and second column of the product $${bm(A36)}${bm(B36)}$ is ___.`, acc: [['8']], sol: r`Row $1$ of the first matrix times column $2$ of the second: $${entryWork(A36, B36, 1, 2)} = 8$.`, d: 2, c: 'application', t: [4] }), (C) => C.blank(entry(mul(A36, B36), 1, 2)));

// =============================================================== Numerical
Q('n01', mk.num({ stem: r`How many elements are there in a matrix of order $3 \times 2$?`, value: 6, sol: r`It has $3$ rows with $2$ elements in each, so the number of elements is $3 \times 2 = 6$.`, scheme: [['6', 1]], d: 1, c: 'recall', t: [1], time: 30 }), (C) => C.val(mat('1 2; 3 4; 5 6').flat().length));
Q('n02', mk.num({ stem: r`Find $x$ if $\begin{bmatrix} 3x - 1 & 7 \\ 2 & 0 \end{bmatrix} = ${M('11 7; 2 0')}$.`, value: 4, sol: r`Equate the elements in the first row and first column: $3x - 1 = 11$, so $3x = 12$ and $x = 4$.`, scheme: [['x = 4', 1]], d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { C.val((11 + 1) / 3); C.sol([12]); });
const A43 = mat('6 -2; 1 5'), B43 = mat('-1 4; 3 2');
Q('n03', mk.num({ stem: r`For $A = ${bm(A43)}$ and $B = ${bm(B43)}$, find the element in the first row and second column of $2A - 3B$.`, value: -16, sol: r`Only that position is needed: $2 \times (-2) - 3 \times 4 = -4 - 12 = -16$.`, scheme: [['−16', 1]], d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.val(entry(sub(scal(2, A43), scal(3, B43)), 1, 2)));
const A44 = mat('3 -2; 1 1');
Q('n04', mk.num({ stem: r`If $A = ${bm(A44)}$, find the sum of the elements on the leading diagonal of $A^2$.`, value: 6, sol: r`First-row, first-column element of $A^2$: $${entryWork(A44, A44, 1, 1)} = 7$. Second-row, second-column element: $${entryWork(A44, A44, 2, 2)} = -1$. Their sum is $7 + (-1) = 6$.`, scheme: [['6', 1]], d: 3, c: 'application', t: [4], time: 90 }), (C) => { C.val(trace(sq(A44))); C.sol([entry(sq(A44), 1, 1), entry(sq(A44), 2, 2)]); });
Q('n05', mk.num({ stem: r`Find $k$ if $\begin{bmatrix} 2 & -1 \\ 3 & k \end{bmatrix} ${M('1; 2')} = ${M('0; 9')}$.`, value: 3, sol: r`Second row: $3 \times 1 + k \times 2 = 9$, so $2k = 6$ and $k = 3$. The first row checks: $2 \times 1 + (-1) \times 2 = 0$.`, scheme: [['k = 3', 1]], d: 2, c: 'application', t: [4], time: 75 }), (C) => { const k = (9 - 3 * 1) / 2; C.val(k); C.assert(key(mul(mat(`2 -1; 3 ${k}`), mat('1; 2'))) === key(mat('0; 9')), 'product checks'); });
const Q46 = mat('4 6; 3 10'), P46 = mat('25; 5');
Q('n06', mk.num({ stem: r`At an imagined fruit stall, Ravi buys $4$ mangoes and $6$ bananas, and Sana buys $3$ mangoes and $10$ bananas. A mango costs ₹25 and a banana ₹5. With $Q = ${bm(Q46)}$ (one row per buyer) and $P = ${bm(P46)}$ (prices in rupees), the product $QP$ gives what each buyer pays. How many rupees does Sana pay?`, value: 125, unit: '₹', sol: r`Sana's amount is the second element of $QP$: $${entryWork(Q46, P46, 2, 1)} = 75 + 50 = 125$, so she pays ₹125.`, scheme: [['₹125', 1]], d: 2, c: 'application', t: [4], time: 90 }), (C) => C.val(entry(mul(Q46, P46), 2, 1)));

// =============================================================== Short answer, 2 marks
const A51 = mat('7; -2'), B51 = O(2);
Q('s201', mk.short({ marks: 2, stem: r`State the order and the type of each matrix: (a) $${bm(A51)}$ (b) $${bm(B51)}$.`, model: J([r`(a) Order $2 \times 1$: a column matrix (it has one column).`, r`(b) Order $2 \times 2$: a square matrix whose elements are all $0$, that is, the zero (null) matrix of order $2$.`]), sol: 'Count the rows, then the columns; then look at the shape and at the elements.', scheme: [['(a) 2 × 1, column matrix', 1], ['(b) 2 × 2, zero (null) square matrix', 1]], d: 1, c: 'understanding', t: [1], time: 60 }), (C) => { C.assert(isCol(A51) && isSquare(B51) && isZero(B51), 'types'); C.model([order(A51), order(B51)]); });
Q('s202', mk.short({ marks: 2, stem: r`$A$ is a $2 \times 2$ matrix and $B$ is a $1 \times 2$ matrix. State, with a reason, whether (a) $AB$ (b) $BA$ is defined, and give the order of any product that is defined.`, model: J([r`(a) $A$ has $2$ columns but $B$ has $1$ row. These are not equal, so $AB$ is not defined.`, r`(b) $B$ has $2$ columns and $A$ has $2$ rows, so $BA$ is defined. Its order is $1 \times 2$ (the rows of $B$ by the columns of $A$).`]), sol: 'A product is defined when the first matrix has as many columns as the second has rows.', scheme: [['(a) not defined, with reason', 1], ['(b) defined, order 1 × 2', 1]], d: 2, c: 'analysis', t: [2], time: 75 }), (C) => { C.assert(!canMulO([2, 2], [1, 2]), '(a)'); C.model([order(O(...prodOrder([1, 2], [2, 2])))]); });
const A53 = mat('4 -1; 0 3'), B53 = mat('2 5; -6 3');
Q('s203', mk.short({ marks: 2, stem: r`Find the matrix $X$ such that $X + ${bm(A53)} = ${bm(B53)}$.`, model: J([r`$X = ${bm(B53)} - ${bm(A53)}$`, r`$= \begin{bmatrix} 2 - 4 & 5 - (-1) \\ -6 - 0 & 3 - 3 \end{bmatrix} = ${M('-2 6; -6 0')}$.`]), sol: 'Subtract the given matrix from the right-hand side, element by element.', scheme: [['X = right side − given matrix', 1], ['X correct', 1]], d: 2, c: 'application', t: [3], time: 75 }), (C) => { const X = sub(B53, A53); C.assert(eqM(add(X, A53), B53), 'check'); C.model([bm(X)]); });
const A54 = mat('2 0; -1 3'), B54 = mat('4; 5');
Q('s204', mk.short({ marks: 2, stem: r`Evaluate $${bm(A54)}${bm(B54)}$ and state the order of the result.`, model: J([`$${bm(A54)}${bm(B54)} = ${prodWork(A54, B54)}$`, r`$= ${M('8; 11')}$, a matrix of order $2 \times 1$.`]), sol: 'Multiply each row of the first matrix by the column, element by element, and add.', scheme: [['Row-by-column working', 1], ['Product and order 2 × 1', 1]], d: 2, c: 'application', t: [4], time: 75 }), (C) => C.model([bm(mul(A54, B54)), order(mul(A54, B54))]));

// =============================================================== Short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`Find $x$ and $y$ if $\begin{bmatrix} x + 2y & 4 \\ 1 & 3x - y \end{bmatrix} = ${M('7 4; 1 7')}$.`, model: J([r`Equating corresponding elements: $x + 2y = 7$ (1) and $3x - y = 7$ (2).`, r`From (2), $y = 3x - 7$. Substituting in (1): $x + 6x - 14 = 7$, so $7x = 21$ and $x = 3$.`, r`Then $y = 3 \times 3 - 7 = 2$. Check in (1): $3 + 2 \times 2 = 7$.`]), sol: 'Equal matrices give one equation for each pair of corresponding elements; solve the two linear equations together.', scheme: [['Two equations formed', 1], ['x = 3', 1], ['y = 2', 1]], d: 2, c: 'application', t: [1], time: 150 }), (C) => { const [x, y] = solveInt(1, 2, 7, 3, -1, 7); C.assert(x === 3 && y === 2 && 7 * x === 21, 'x = 3, y = 2'); C.model([21, x, y]); });
const A62 = mat('2 -3; 4 1'), B62 = mat('0 5; -2 6');
Q('s302', mk.short({ marks: 3, stem: r`If $A = ${bm(A62)}$ and $B = ${bm(B62)}$, evaluate $3A - 2B$.`, model: J([`$3A = ${M('6 -9; 12 3')}$ and $2B = ${M('0 10; -4 12')}$.`, r`$3A - 2B = \begin{bmatrix} 6 - 0 & -9 - 10 \\ 12 - (-4) & 3 - 12 \end{bmatrix} = ${M('6 -19; 16 -9')}$.`]), sol: 'Multiply each matrix by its number first, then subtract corresponding elements.', scheme: [['3A', 1], ['2B', 1], ['3A − 2B', 1]], d: 2, c: 'application', t: [3], time: 120 }), (C) => C.model([bm(scal(3, A62)), bm(scal(2, B62)), bm(sub(scal(3, A62), scal(2, B62)))]));
const A63 = mat('2 1; 0 -3'), B63 = mat('1 -1; 4 2');
Q('s303', mk.short({ marks: 3, stem: r`Given $A = ${bm(A63)}$ and $B = ${bm(B63)}$, find $AB$ and $BA$. Is $AB = BA$?`, model: J([`$AB = ${prodWork(A63, B63)} = ${M('6 0; -12 -6')}$.`, `$BA = ${prodWork(B63, A63)} = ${M('2 4; 8 -2')}$.`, r`The corresponding elements differ (for example $6 \ne 2$ in the first place), so $AB \ne BA$: matrix multiplication is not commutative.`]), sol: 'Multiply in both orders and compare the elements in the same places.', scheme: [['AB', 1], ['BA', 1], ['AB ≠ BA concluded', 1]], d: 2, c: 'application', t: [4], time: 150 }), (C) => { C.assert(!eqM(mul(A63, B63), mul(B63, A63)), 'not equal'); C.model([bm(mul(A63, B63)), bm(mul(B63, A63))]); });
const A64 = mat('3 -2; 1 4'), R64 = mat('8; 12');
Q('s304', mk.short({ marks: 3, stem: r`Find $x$ and $y$ if $${bm(A64)} \begin{bmatrix} x \\ y \end{bmatrix} = ${bm(R64)}$.`, model: J([r`$${bm(A64)} \begin{bmatrix} x \\ y \end{bmatrix} = \begin{bmatrix} 3x - 2y \\ x + 4y \end{bmatrix}$, so $3x - 2y = 8$ and $x + 4y = 12$.`, r`Multiply the first equation by $2$ and add the second: $7x = 28$, so $x = 4$.`, r`Then $4y = 12 - 4 = 8$, so $y = 2$.`]), sol: 'Multiply out the left side, equate corresponding elements and solve the two linear equations.', scheme: [['Product written and equations formed', 1], ['x = 4', 1], ['y = 2', 1]], d: 2, c: 'application', t: [4], time: 150 }), (C) => { const [x, y] = solveInt(3, -2, 8, 1, 4, 12); C.assert(key(mul(A64, [[x], [y]])) === key(R64), 'product checks'); C.model([28, x, 8, y]); });
const A65 = mat('5 -1; 2 6'), B65 = mat('3 7; -4 2');
Q('s305', mk.short({ marks: 3, stem: r`Given $A = ${bm(A65)}$ and $B = ${bm(B65)}$, find the matrix $X$ for which $\dfrac{1}{2}X + A = B$.`, model: J([r`$\dfrac{1}{2}X = B - A = ${M('-2 8; -6 -4')}$.`, r`Multiplying by $2$: $X = ${M('-4 16; -12 -8')}$.`, r`Check: $\dfrac{1}{2}X + A = ${M('-2 8; -6 -4')} + ${bm(A65)} = ${bm(B65)}$.`]), sol: 'Isolate the term in X, then multiply by 2.', scheme: [['B − A', 1], ['Multiplied by 2', 1], ['X with check', 1]], d: 2, c: 'application', t: [3], time: 150 }), (C) => { const X = scal(2, sub(B65, A65)); C.assert(eqM(add(scal([1, 2], X), A65), B65), 'check'); C.model([bm(sub(B65, A65)), bm(X)]); });

// =============================================================== Short answer, 4 marks
const A71 = mat('5 -2; 3 -1');
Q('s401', mk.short({ marks: 4, stem: r`If $A = ${bm(A71)}$, show that $A^2 - 4A + I = O$, where $I$ is the identity matrix and $O$ the zero matrix of order $2$.`, model: J([`$A^2 = ${prodWork(A71, A71)} = ${M('19 -8; 12 -5')}$.`, `$4A = ${M('20 -8; 12 -4')}$.`, r`$A^2 - 4A + I = \begin{bmatrix} 19 - 20 + 1 & -8 + 8 + 0 \\ 12 - 12 + 0 & -5 + 4 + 1 \end{bmatrix}$`, `$= ${M('0 0; 0 0')} = O$.`]), sol: 'Find the square by the row-by-column rule, then combine corresponding elements.', scheme: [['A² working', 1], ['A² correct', 1], ['4A', 1], ['Sum is O', 1]], d: 3, c: 'application', t: [3, 4], time: 240 }), (C) => { C.assert(isZero(add(sub(sq(A71), scal(4, A71)), I2)), 'identity holds'); C.model([bm(sq(A71)), bm(scal(4, A71))]); });
const A72 = mat('1 -1; 2 0'), B72 = mat('4 2; 1 1');
Q('s402', mk.short({ marks: 4, stem: r`Let $A = ${bm(A72)}$ and $B = ${bm(B72)}$. Find the matrix $C$ such that $AB - C = 2A$.`, model: J([`$AB = ${prodWork(A72, B72)} = ${M('3 1; 8 4')}$.`, `$2A = ${M('2 -2; 4 0')}$.`, r`From $AB - C = 2A$ we get $C = AB - 2A$.`, `$C = ${M('3 1; 8 4')} - ${M('2 -2; 4 0')} = ${M('1 3; 4 4')}$.`]), sol: 'Rearrange for C first, then compute the product and the multiple of A.', scheme: [['AB', 2], ['2A', 1], ['C', 1]], d: 3, c: 'application', t: [3, 4], time: 240 }), (C) => { const AB = mul(A72, B72), Cm = sub(AB, scal(2, A72)); C.assert(eqM(sub(AB, Cm), scal(2, A72)), 'AB - C = 2A'); C.model([bm(AB), bm(scal(2, A72)), bm(Cm)]); });
const A73 = mat('2 -1; 1 0'), B73 = mat('0 1; 3 2');
const S73 = add(A73, B73), D73 = sub(A73, B73);
Q('s403', mk.short({ marks: 4, stem: r`For $A = ${bm(A73)}$ and $B = ${bm(B73)}$, show that $(A + B)(A - B) \ne A^2 - B^2$, and explain why the identity from algebra fails for these matrices.`, model: J([`$A + B = ${M('2 0; 4 2')}$ and $A - B = ${M('2 -2; -2 -2')}$.`, `$(A + B)(A - B) = ${prodWork(S73, D73)} = ${M('4 -4; 4 -12')}$.`, `$A^2 = ${M('3 -2; 2 -1')}$ and $B^2 = ${M('3 2; 6 7')}$, so $A^2 - B^2 = ${M('0 -4; -4 -8')}$, which is different.`, r`Reason: $(A + B)(A - B) = A^2 - AB + BA - B^2$. Here $AB = ${M('-3 0; 0 1')}$ and $BA = ${M('1 0; 8 -3')}$, so $BA - AB = ${M('4 0; 8 -4')} \ne O$, and this is exactly the difference between the two results.`]), sol: 'Compute both sides separately; then expand the product, keeping AB and BA apart.', scheme: [['A + B and A − B', 1], ['(A + B)(A − B)', 1], ['A² − B²', 1], ['Reason: AB ≠ BA', 1]], d: 3, c: 'analysis', t: [3, 4], time: 300 }), (C) => {
  const L = mul(S73, D73), R = sub(sq(A73), sq(B73)), K = sub(mul(B73, A73), mul(A73, B73));
  C.assert(!eqM(L, R) && eqM(sub(L, R), K), 'differ by BA - AB');
  C.model([bm(S73), bm(D73), bm(L), bm(sq(A73)), bm(sq(B73)), bm(R), bm(mul(A73, B73)), bm(mul(B73, A73)), bm(K)]);
});
const S74 = mat('20 35; 15 40'), P74 = mat('120; 30');
Q('s404', mk.short({ marks: 4, stem: r`An imagined bakery has two outlets. On one day outlet 1 sells $20$ cakes and $35$ loaves of bread, and outlet 2 sells $15$ cakes and $40$ loaves. A cake costs ₹120 and a loaf ₹30. (a) Write the sales matrix $S$, with one row per outlet, and the price matrix $P$ as a column. (b) Find $SP$. (c) Which outlet takes more money that day, and by how much?`, model: J([`(a) $S = ${M('20 35; 15 40')}$ (order $2 \\times 2$) and $P = ${M('120; 30')}$ (order $2 \\times 1$).`, `(b) $SP = ${prodWork(S74, P74)} = ${M('3450; 3000')}$.`, r`(c) Outlet 1 takes ₹3,450 and outlet 2 takes ₹3,000, so outlet 1 takes ₹450 more ($3450 - 3000 = 450$).`]), sol: 'Arrange quantities by rows and prices as a column so that the product gives each outlet its takings.', scheme: [['(a) S and P', 1], ['(b) working', 1], ['(b) SP', 1], ['(c) outlet 1, ₹450 more', 1]], d: 2, c: 'application', t: [4], time: 240 }), (C) => { const SP = mul(S74, P74); C.model([bm(S74), bm(P74), bm(SP), SP[0][0] - SP[1][0]]); C.assert(SP[0][0] > SP[1][0], 'outlet 1 more'); });
Q('s405', mk.short({ marks: 4, stem: r`Find $x$, $y$ and $z$ if $2\begin{bmatrix} x & 3 \\ -1 & y \end{bmatrix} + \begin{bmatrix} 4 & z \\ 6 & -2 \end{bmatrix} = ${M('10 8; 4 6')}$.`, model: J([r`$2\begin{bmatrix} x & 3 \\ -1 & y \end{bmatrix} = \begin{bmatrix} 2x & 6 \\ -2 & 2y \end{bmatrix}$, so the left side is $\begin{bmatrix} 2x + 4 & 6 + z \\ 4 & 2y - 2 \end{bmatrix}$.`, r`Equating corresponding elements: $2x + 4 = 10$, so $x = 3$.`, r`$6 + z = 8$, so $z = 2$.`, r`$2y - 2 = 6$, so $y = 4$. The remaining elements agree: $-2 + 6 = 4$.`]), sol: 'Multiply the first matrix by 2, add, then equate corresponding elements one at a time.', scheme: [['Left side simplified', 1], ['x = 3', 1], ['z = 2', 1], ['y = 4', 1]], d: 2, c: 'application', t: [1, 3], time: 240 }), (C) => { const [x, y, z] = [(10 - 4) / 2, (6 + 2) / 2, 8 - 6]; C.assert(eqM(add(scal(2, mat(`${x} 3; -1 ${y}`)), mat(`4 ${z}; 6 -2`)), mat('10 8; 4 6')), 'equation holds'); C.model([x, z, y]); });
const A76 = mat('3 2; 1 5');
Q('s406', mk.short({ marks: 4, stem: r`If $A = ${bm(A76)}$, find the numbers $p$ and $q$ for which $A^2 = pA + qI$.`, model: J([`$A^2 = ${prodWork(A76, A76)} = ${M('11 16; 8 27')}$.`, r`$pA + qI = \begin{bmatrix} 3p + q & 2p \\ p & 5p + q \end{bmatrix}$.`, r`Equating elements: $2p = 16$ gives $p = 8$; then $3p + q = 11$ gives $q = 11 - 24 = -13$.`, r`Check the other elements: $p = 8$ and $5p + q = 40 - 13 = 27$.`]), sol: 'Square A, write pA + qI with letters, and compare the elements; use the spare elements as a check.', scheme: [['A²', 1], ['pA + qI', 1], ['p = 8', 1], ['q = −13 with check', 1]], d: 3, c: 'analysis', t: [3, 4], time: 240 }), (C) => { const A2 = sq(A76), p = A2[0][1] / A76[0][1], q = A2[0][0] - p * A76[0][0]; C.assert(eqM(A2, add(scal(p, A76), scal(q, I2))), 'A^2 = pA + qI'); C.model([bm(A2), p, q]); });

// =============================================================== Long answer, 10 marks (3 + 3 + 4)
const A81 = mat('2 -1; 0 4'), B81 = mat('-3 2; 1 5');
Q('l01', mk.long({ marks: 10, stem: r`Answer each part.
(a) Find $a$, $b$ and $c$ if $\begin{bmatrix} a + b & 3 \\ 2c - 1 & a - b \end{bmatrix} = ${M('9 3; 5 1')}$.
(b) Given $A = ${bm(A81)}$ and $B = ${bm(B81)}$, find $2A + 3B$.
(c) For the same $A$ and $B$, find $AB$ and $BA$, and state what the result shows about matrix multiplication.`, model: J([r`(a) Equating corresponding elements: $a + b = 9$ and $a - b = 1$. Adding, $2a = 10$, so $a = 5$ and $b = 4$.`, r`Also $2c - 1 = 5$, so $2c = 6$ and $c = 3$.`, `(b) $2A = ${M('4 -2; 0 8')}$ and $3B = ${M('-9 6; 3 15')}$, so $2A + 3B = ${M('-5 4; 3 23')}$.`, `(c) $AB = ${prodWork(A81, B81)} = ${M('-7 -1; 4 20')}$.`, `$BA = ${prodWork(B81, A81)} = ${M('-6 11; 2 19')}$.`, r`Since $AB \ne BA$, matrix multiplication is not commutative.`]), sol: 'Part (a): one equation per pair of corresponding elements. Part (b): scalar multiples first. Part (c): multiply in both orders and compare.', scheme: [['(a) a + b = 9 and a − b = 1', 1], ['(a) a = 5, b = 4, c = 3', 2], ['(b) 2A and 3B', 2], ['(b) 2A + 3B', 1], ['(c) AB', 2], ['(c) BA', 1], ['(c) AB ≠ BA stated', 1]], d: 3, c: 'application', t: [1, 3, 4], time: 600 }), (C) => {
  const [a, b] = solveInt(1, 1, 9, 1, -1, 1), c = (5 + 1) / 2;
  C.assert(a === 5 && b === 4 && c === 3, '(a)');
  C.assert(!eqM(mul(A81, B81), mul(B81, A81)), '(c) not equal');
  C.model([a, b, c, bm(scal(2, A81)), bm(scal(3, B81)), bm(add(scal(2, A81), scal(3, B81))), bm(mul(A81, B81)), bm(mul(B81, A81))]);
});
const A82 = mat('1 4; -3 0'), B82 = mat('5 -2; 7 6'), N82 = mat('4 3; 2 -1'), V82 = mat('3; 2');
Q('l02', mk.long({ marks: 10, stem: r`Answer each part.
(a) $A$ is of order $2 \times 2$, $B$ of order $2 \times 1$ and $C$ of order $1 \times 2$. Which of the products $AB$, $BA$, $CA$ and $AC$ are defined? Give the order of each product that is defined.
(b) Solve the matrix equation $2X - A = B$ for $A = ${bm(A82)}$ and $B = ${bm(B82)}$.
(c) Find $x$ and $y$ if $\begin{bmatrix} 4 & x \\ y & -1 \end{bmatrix} ${M('2; 3')} = ${M('17; 1')}$, and hence evaluate $\begin{bmatrix} 4 & x \\ y & -1 \end{bmatrix} \begin{bmatrix} x \\ y \end{bmatrix}$.`, model: J([r`(a) $AB$: $A$ has $2$ columns and $B$ has $2$ rows, so it is defined, of order $2 \times 1$. $BA$: $B$ has $1$ column but $A$ has $2$ rows, so it is not defined.`, r`$CA$: $C$ has $2$ columns and $A$ has $2$ rows, so it is defined, of order $1 \times 2$. $AC$: $A$ has $2$ columns but $C$ has $1$ row, so it is not defined.`, r`(b) $2X = A + B = ${M('6 2; 4 6')}$, so $X = \dfrac{1}{2}${M('6 2; 4 6')} = ${M('3 1; 2 3')}$.`, r`(c) Row by column: $8 + 3x = 17$ and $2y - 3 = 1$. So $3x = 9$, giving $x = 3$, and $2y = 4$, giving $y = 2$.`, `Then $${bm(N82)}${bm(V82)} = ${prodWork(N82, V82)} = ${M('18; 4')}$.`]), sol: 'Part (a): compare columns of the first with rows of the second. Part (b): make 2X the subject. Part (c): multiply out, equate, then substitute.', scheme: [['(a) AB defined, 2 × 1; BA not defined', 1.5], ['(a) CA defined, 1 × 2; AC not defined', 1.5], ['(b) 2X = A + B', 1], ['(b) X', 2], ['(c) two equations', 1], ['(c) x = 3, y = 2', 1.5], ['(c) product', 1.5]], d: 3, c: 'application', t: [2, 3, 4], time: 600 }), (C) => {
  const o = { A: [2, 2], B: [2, 1], C: [1, 2] };
  C.assert(ok(prodOrder(o.A, o.B)) === '2x1' && !canMulO(o.B, o.A) && ok(prodOrder(o.C, o.A)) === '1x2' && !canMulO(o.A, o.C), '(a)');
  const X = scal([1, 2], add(A82, B82));
  C.assert(eqM(sub(scal(2, X), A82), B82), '(b) check');
  const x = (17 - 4 * 2) / 3, y = (1 + 1 * 3) / 2;
  C.assert(key(mul(mat(`4 ${x}; ${y} -1`), mat('2; 3'))) === key(mat('17; 1')) && key(N82) === key(mat(`4 ${x}; ${y} -1`)) && key(V82) === key(mat(`${x}; ${y}`)), '(c) x, y');
  C.model([bm(add(A82, B82)), bm(X), x, y, bm(mul(N82, V82))]);
});
const A83 = mat('4 -1; 3 -1'), P83 = mat('2 -1; 3 2'), Q83 = mat('1 0; 2 -2'), R83 = mat('0 3; -1 1');
Q('l03', mk.long({ marks: 10, stem: r`Answer each part.
(a) Find $x$ and $y$ if $\begin{bmatrix} x & 3 \\ 2 & y \end{bmatrix} + \begin{bmatrix} -y & 1 \\ x & 4 \end{bmatrix} = ${M('1 4; 7 8')}$.
(b) If $A = ${bm(A83)}$, show that $A^2 - 3A = I$.
(c) For $P = ${bm(P83)}$, $Q = ${bm(Q83)}$ and $R = ${bm(R83)}$, verify that $P(Q + R) = PQ + PR$.`, model: J([r`(a) Adding the left side: $\begin{bmatrix} x - y & 4 \\ 2 + x & y + 4 \end{bmatrix} = ${M('1 4; 7 8')}$.`, r`So $2 + x = 7$, giving $x = 5$, and $y + 4 = 8$, giving $y = 4$. Check: $x - y = 5 - 4 = 1$.`, `(b) $A^2 = ${prodWork(A83, A83)} = ${M('13 -3; 9 -2')}$.`, r`$3A = ${M('12 -3; 9 -3')}$, so $A^2 - 3A = ${M('1 0; 0 1')} = I$.`, `(c) $Q + R = ${M('1 3; 1 -1')}$, so $P(Q + R) = ${prodWork(P83, add(Q83, R83))} = ${M('1 7; 5 7')}$.`, `$PQ = ${M('0 2; 7 -4')}$ and $PR = ${M('1 5; -2 11')}$, so $PQ + PR = ${M('1 7; 5 7')}$.`, r`Hence $P(Q + R) = PQ + PR$.`]), sol: 'Part (a): add first, then equate. Part (b): square by the row-by-column rule. Part (c): work out both sides separately.', scheme: [['(a) equations from equal elements', 1], ['(a) x = 5, y = 4', 2], ['(b) A²', 2], ['(b) A² − 3A = I', 1], ['(c) P(Q + R)', 2], ['(c) PQ and PR', 1], ['(c) equality shown', 1]], d: 3, c: 'application', t: [1, 3, 4], time: 600 }), (C) => {
  const x = 7 - 2, y = 8 - 4;
  C.assert(eqM(add(mat(`${x} 3; 2 ${y}`), mat(`${-y} 1; ${x} 4`)), mat('1 4; 7 8')), '(a)');
  C.assert(eqM(sub(sq(A83), scal(3, A83)), I2), '(b)');
  const L = mul(P83, add(Q83, R83)), Rr = add(mul(P83, Q83), mul(P83, R83));
  C.assert(eqM(L, Rr), '(c)');
  C.model([x, y, bm(sq(A83)), bm(scal(3, A83)), bm(add(Q83, R83)), bm(L), bm(mul(P83, Q83)), bm(mul(P83, R83))]);
});
const A84 = mat('1 -3; 2 0'), B84 = mat('0 2; -1 4'), P84 = mat('3 -6; 1 -2'), Q84 = mat('4 2; 2 1');
Q('l04', mk.long({ marks: 10, stem: r`Answer each part.
(a) For $A = ${bm(A84)}$ and $B = ${bm(B84)}$, find $A + B$ and $A - B$, and verify that their sum is $2A$.
(b) Find $p$ and $q$ if $${M('3 1; -1 4')} \begin{bmatrix} p \\ q \end{bmatrix} = ${M('6; 11')}$.
(c) For $P = ${bm(P84)}$ and $Q = ${bm(Q84)}$, find $PQ$ and $QP$. What do the results show about products of non-zero matrices, and about the order of multiplication?`, model: J([`(a) $A + B = ${M('1 -1; 1 4')}$ and $A - B = ${M('1 -5; 3 -4')}$.`, `$(A + B) + (A - B) = ${M('2 -6; 4 0')}$, and $2A = ${M('2 -6; 4 0')}$, so the two are equal.`, r`(b) Row by column: $3p + q = 6$ and $-p + 4q = 11$. From the first, $q = 6 - 3p$; then $-p + 24 - 12p = 11$, so $13p = 13$.`, r`So $p = 1$ and $q = 6 - 3 = 3$.`, `(c) $PQ = ${prodWork(P84, Q84)} = ${M('0 0; 0 0')}$, the zero matrix.`, `$QP = ${prodWork(Q84, P84)} = ${M('14 -28; 7 -14')}$.`, r`So the product of two non-zero matrices can be the zero matrix, and $PQ \ne QP$: the order of multiplication matters.`]), sol: 'Part (a): element by element. Part (b): multiply out and solve the pair of equations. Part (c): multiply in both orders.', scheme: [['(a) A + B and A − B', 2], ['(a) sum equals 2A', 1], ['(b) equations', 1], ['(b) p = 1, q = 3', 2], ['(c) PQ = O', 1.5], ['(c) QP', 1.5], ['(c) conclusions', 1]], d: 3, c: 'analysis', t: [3, 4], time: 600 }), (C) => {
  C.assert(eqM(add(add(A84, B84), sub(A84, B84)), scal(2, A84)), '(a)');
  const [p, q] = solveInt(3, 1, 6, -1, 4, 11);
  C.assert(key(mul(mat('3 1; -1 4'), [[p], [q]])) === key(mat('6; 11')) && 13 * p === 13 && 6 - 3 * p === q, '(b)');
  C.assert(isZero(mul(P84, Q84)) && !isZero(mul(Q84, P84)) && !isZero(P84) && !isZero(Q84), '(c)');
  C.model([bm(add(A84, B84)), bm(sub(A84, B84)), bm(scal(2, A84)), p, q, bm(mul(P84, Q84)), bm(mul(Q84, P84))]);
});
const A85 = mat('3 4; -2 1'), N85 = mat('1 0; 3 1'), R85 = mat('5 1; 7 3');
Q('l05', mk.long({ marks: 10, stem: r`Answer each part.
(a) Find $x$ and $y$ if $\begin{bmatrix} 2 & x - y \\ x + y & 5 \end{bmatrix} = ${M('2 -1; 7 5')}$.
(b) If $A = ${bm(A85)}$ and $I$ is the identity matrix of order $2$, find $(A - 2I)(A + I)$.
(c) Find the $2 \times 2$ matrix $X$ such that $X ${bm(N85)} = ${bm(R85)}$.`, model: J([r`(a) Equating corresponding elements: $x - y = -1$ and $x + y = 7$. Adding, $2x = 6$, so $x = 3$; then $y = 7 - 3 = 4$.`, `(b) $A - 2I = ${M('1 4; -2 -1')}$ and $A + I = ${M('4 4; -2 2')}$.`, `$(A - 2I)(A + I) = ${prodWork(sub(A85, scal(2, I2)), add(A85, I2))} = ${M('-4 12; -6 -10')}$.`, r`(c) Let $X = \begin{bmatrix} a & b \\ c & d \end{bmatrix}$. Then $X ${bm(N85)} = \begin{bmatrix} a + 3b & b \\ c + 3d & d \end{bmatrix}$.`, r`Equating with $${bm(R85)}$: $b = 1$ and $a + 3b = 5$, so $a = 2$; $d = 3$ and $c + 3d = 7$, so $c = -2$.`, `So $X = ${M('2 1; -2 3')}$. Check: $${M('2 1; -2 3')}${bm(N85)} = ${bm(R85)}$.`]), sol: 'Part (a): two equations from equal elements. Part (b): form each bracket first. Part (c): write X with four letters, multiply out and equate.', scheme: [['(a) x − y = −1 and x + y = 7', 1], ['(a) x = 3, y = 4', 2], ['(b) A − 2I and A + I', 1], ['(b) product', 2], ['(c) product in a, b, c, d', 1.5], ['(c) a = 2, b = 1, c = −2, d = 3', 1.5], ['(c) X with check', 1]], d: 4, c: 'analysis', t: [1, 3, 4], time: 660 }), (C) => {
  const [x, y] = solveInt(1, -1, -1, 1, 1, 7);
  const Pm = mul(sub(A85, scal(2, I2)), add(A85, I2));
  C.assert(eqM(Pm, sub(sub(sq(A85), A85), scal(2, I2))), '(b) equals A^2 - A - 2I');
  const b = R85[0][1], a = R85[0][0] - 3 * b, dd = R85[1][1], c = R85[1][0] - 3 * dd, X = [[a, b], [c, dd]];
  C.assert(eqM(mul(X, N85), R85), '(c) X N = R');
  C.model([x, y, bm(sub(A85, scal(2, I2))), bm(add(A85, I2)), bm(Pm), a, b, c, dd, bm(X)]);
});
const R86 = mat('5 -2'), S86 = mat('1 3; 4 -1'), B86 = mat('6 4; -2 0'), A86 = mat('2 3; 0 1');
Q('l06', mk.long({ marks: 10, stem: r`Answer each part.
(a) State the order of the product $${bm(R86)}${bm(S86)}$ and evaluate it.
(b) If $B = ${bm(B86)}$, find $\dfrac{1}{2}B + 3I$, where $I$ is the identity matrix of order $2$.
(c) If $A = \begin{bmatrix} 2 & x \\ 0 & 1 \end{bmatrix}$ and $A^2 = ${M('4 9; 0 1')}$, find $x$. Hence show that $A^2 - 3A + 2I = O$.`, model: J([r`(a) A $1 \times 2$ matrix times a $2 \times 2$ matrix is defined, and the product has order $1 \times 2$.`, `$${bm(R86)}${bm(S86)} = ${prodWork(R86, S86)} = ${M('-3 17')}$.`, r`(b) $\dfrac{1}{2}B = ${M('3 2; -1 0')}$ and $3I = ${M('3 0; 0 3')}$, so $\dfrac{1}{2}B + 3I = ${M('6 2; -1 3')}$.`, r`(c) $A^2 = \begin{bmatrix} 2 & x \\ 0 & 1 \end{bmatrix} \begin{bmatrix} 2 & x \\ 0 & 1 \end{bmatrix} = \begin{bmatrix} 4 & 2x + x \\ 0 & 1 \end{bmatrix} = \begin{bmatrix} 4 & 3x \\ 0 & 1 \end{bmatrix}$. Comparing with $${M('4 9; 0 1')}$: $3x = 9$, so $x = 3$.`, r`With $A = ${bm(A86)}$: $3A = ${M('6 9; 0 3')}$, and $A^2 - 3A + 2I = \begin{bmatrix} 4 - 6 + 2 & 9 - 9 + 0 \\ 0 - 0 + 0 & 1 - 3 + 2 \end{bmatrix} = ${M('0 0; 0 0')} = O$.`]), sol: 'Part (a): rows of the first by columns of the second. Part (b): halve every element, then add 3 on the leading diagonal. Part (c): square A with the letter in place, compare, then substitute.', scheme: [['(a) order 1 × 2', 1], ['(a) product', 2], ['(b) ½B and 3I', 2], ['(b) sum', 1], ['(c) A² in terms of x', 1.5], ['(c) x = 3', 1], ['(c) A² − 3A + 2I = O', 1.5]], d: 3, c: 'application', t: [2, 3, 4], time: 600 }), (C) => {
  C.assert(ok(prodOrder([1, 2], [2, 2])) === '1x2', '(a) order');
  const x = 9 / 3;
  C.assert(key(sq(mat(`2 ${x}; 0 1`))) === key(mat('4 9; 0 1')) && key(A86) === key(mat(`2 ${x}; 0 1`)) && isZero(add(sub(sq(A86), scal(3, A86)), scal(2, I2))), '(c)');
  C.model([bm(mul(R86, S86)), bm(scal([1, 2], B86)), bm(scal(3, I2)), bm(add(scal([1, 2], B86), scal(3, I2))), x, bm(scal(3, A86))]);
});
const M87 = mat('2 -5; 0 7'), V87 = mat('1; 3'), W87 = mat('15 5; 12 2'), S87 = mat('4; -1'), A87 = mat('-1 4; 2 3');
const Y87 = sub(scal(2, A87), scal(3, I2));
Q('l07', mk.long({ marks: 10, stem: r`Answer each part.
(a) Explain why the product $${bm(M87)}${bm(V87)}$ is defined, state its order, and evaluate it.
(b) In an imagined inter-house quiz, a correct answer earns $4$ points and a wrong answer costs $1$ point. House Tagore gives $15$ correct and $5$ wrong answers; House Raman gives $12$ correct and $2$ wrong. Using $W = ${bm(W87)}$ and $S = ${bm(S87)}$, find $WS$, and say which house leads and by how many points.
(c) If $A = ${bm(A87)}$ and $Y = 2A - 3I$, find $Y$ and show that $AY = YA$.`, model: J([r`(a) The first matrix has $2$ columns and the second has $2$ rows, so the product is defined; its order is $2 \times 1$.`, `$${bm(M87)}${bm(V87)} = ${prodWork(M87, V87)} = ${M('-13; 21')}$.`, `(b) $WS = ${prodWork(W87, S87)} = ${M('55; 46')}$.`, r`House Tagore scores $55$ points and House Raman $46$, so Tagore leads by $55 - 46 = 9$ points.`, `(c) $Y = 2A - 3I = ${M('-2 8; 4 6')} - ${M('3 0; 0 3')} = ${M('-5 8; 4 3')}$.`, `$AY = ${prodWork(A87, Y87)} = ${M('21 4; 2 25')}$.`, `$YA = ${prodWork(Y87, A87)} = ${M('21 4; 2 25')}$, so $AY = YA$.`]), sol: 'Part (a): columns of the first must equal rows of the second. Part (b): the product totals each house. Part (c): form Y, then multiply in both orders.', scheme: [['(a) reason and order 2 × 1', 1], ['(a) product', 2], ['(b) WS', 2], ['(b) Tagore leads by 9 points', 1], ['(c) Y', 1], ['(c) AY', 1.5], ['(c) YA and conclusion', 1.5]], d: 3, c: 'application', t: [2, 3, 4], time: 600 }), (C) => {
  const WS = mul(W87, S87);
  C.assert(eqM(mul(A87, Y87), mul(Y87, A87)), '(c) AY = YA');
  C.model([bm(mul(M87, V87)), bm(WS), WS[0][0] - WS[1][0], bm(scal(2, A87)), bm(scal(3, I2)), bm(Y87), bm(mul(A87, Y87))]);
});
